function stableSortEventsByTs(arr){
  if (arr.length < 2) return arr;
  const mid = Math.floor(arr.length/2);
  const left = stableSortEventsByTs(arr.slice(0, mid));
  const right = stableSortEventsByTs(arr.slice(mid));
  const merged = [];
  let i=0, j=0;
  while (i<left.length && j<right.length){
    if (left[i].ts <= right[j].ts){
      merged.push(left[i++]);
    } else {
      merged.push(right[j++]);
    }
  }
  return merged.concat(left.slice(i)).concat(right.slice(j));
}
```

